'use strict';
let friendCpuChallenge=null,friendCpuLoading=false,friendCpuSetupTimer=null,friendCpuSetupSignature='',friendCpuSetupSyncing=false;
window.startFriendCpuBattle=async code=>{
 if(friendCpuLoading||friendBusy)return;
 if(friendRoom||typeof onlineSearching!=='undefined'&&onlineSearching){friendListMessage('参加中の対局・オンライン検索を終了してから挑戦できます。');return;}
 const team=gameState.deck.map(id=>gameState.inventory.find(i=>i.instanceId===id)).filter(Boolean);
 if(team.length!==3){friendListMessage('文字タブで出撃用デッキに文字を3体編成してください。');return;}
 friendCpuLoading=true;friendListBusy=true;renderFriendDirectory();friendListMessage('フレンドの編成を読み込み中…');
 try{const response=await playerApi(`/api/friends/${code}/cpu`);if(friendRoom||typeof onlineSearching!=='undefined'&&onlineSearching)throw Error('参加中の対局・オンライン検索を終了してから挑戦してください。');friendCpuChallenge={code:response.code,profile:response.profile,enemies:response.team.items,enemyFormation:response.team.formation,team:team.map(i=>({...i,equippedReadings:getEquippedReadings(i).slice(),unlockedReadings:getUnlockedReadings(i).slice()})),formation:KanjiFormation.copy(getActiveFormation())};
  setAutoBattle(false);setAutoContinue(false);endlessRun=null;specialChallenge=null;practiceRun=null;battleMode='friend-cpu';document.getElementById('modal-friends').classList.add('hidden');document.getElementById('modal-result').classList.add('hidden');switchTab('battle');resetBattle(false,true);paintFriendCpuIdentity();friendListMessage('');
 }catch(error){friendListMessage(error.message);}finally{friendCpuLoading=false;friendListBusy=false;renderFriendDirectory();}
};
function paintFriendCpuIdentity(){const avatar=document.getElementById('battle-peer-icon');if(avatar){avatar.hidden=false;paintPlayerAvatar(avatar,friendCpuChallenge.profile);}document.getElementById('cpu-name').textContent=friendCpuChallenge.profile.name+'のCPU';document.getElementById('cpu-rank').textContent='フレンド腕試し・育成状態を反映／操作は強敵相当で固定';}
window.retryFriendCpuBattle=()=>{if(battleMode!=='friend-cpu'||!friendCpuChallenge)return;setAutoBattle(false);document.getElementById('modal-result').classList.add('hidden');document.getElementById('modal-battle-menu').classList.add('hidden');resetBattle(false,true);paintFriendCpuIdentity();};
window.endFriendCpuBattle=()=>{setAutoBattle(false);setAutoContinue(false);clearTimeout(cpuTurnTimer);clearTimeout(playerTurnTimer);friendCpuChallenge=null;battleMode='classic';document.getElementById('modal-result').classList.add('hidden');document.getElementById('modal-battle-menu').classList.add('hidden');resetBattle();switchTab('matches');openFriendLobby();setFriendLobbyTab('list');};
window.finishFriendCpuBattle=(winner,verdict)=>{isBattleEnded=true;playSound(winner?'win':'lose');document.getElementById('result-title-badge').textContent=winner===null?'引き分け':winner?'勝 利':'敗 北';document.getElementById('result-title-badge').className='text-4xl font-extrabold kanji-font text-amber-400 tracking-widest my-2';document.getElementById('result-message').textContent=friendCpuChallenge.profile.name+'の保存した編成とのCPU対戦です。'+(verdict?verdict.reason+'で決着。':'')+'段位ポイント・対人RP・経験値は変動しません。';document.getElementById('result-rp-change').textContent='ポイント変動なし';document.getElementById('result-coin-change').textContent='文の変動なし';document.getElementById('result-exp-info').hidden=true;for(const id of ['btn-friend-next','btn-friend-result-deck','btn-result-room-exit','btn-endless-next','btn-special-next','btn-special-retry','btn-online-result-next','btn-practice-retry'])document.getElementById(id).hidden=true;document.getElementById('btn-result-close').textContent='同じ編成でもう一度';document.getElementById('btn-cpu-result-end').hidden=false;document.getElementById('modal-result').classList.remove('hidden');saveState(true);};
// Growth is refreshed without changing the selected multiplayer lineup or its rubies.
window.queueFriendCpuSetupSync=()=>{clearTimeout(friendCpuSetupTimer);friendCpuSetupTimer=setTimeout(syncFriendCpuSetup,1200);};
async function syncFriendCpuSetup(){if(friendCpuSetupSyncing||saveRecoveryBlocked||friendDeckSaving)return;friendCpuSetupSyncing=true;try{await loadFriendSetup();const team=resolvedFriendSetup();if(team.items.length!==3)return;const signature=JSON.stringify(team);if(signature===friendCpuSetupSignature)return;await playerApi('/api/friends/setup','PUT',team);friendCpuSetupSignature=signature;}catch{}finally{friendCpuSetupSyncing=false;}}
queueFriendCpuSetupSync();
window.addEventListener('online',queueFriendCpuSetupSync);
